function diagnosticNodeTarget(nodes: SimulationNode[], event: SimulationResult['diagnostics'][number]) {
  const byEvidence = nodes.find(node => event.evidence.includes(node.name) || event.evidence.includes(node.id))
  if (byEvidence) return byEvidence
  const kindByDiagnostic: Record<string, Kind> = {
    'inverter-overload': 'inverter', 'startup-surge': 'inverter', 'controller-limit': 'mppt',
    'battery-charge-limit': 'mppt', 'battery-current-limit': 'battery', 'protection-current': 'fuse',
    'protection-overcurrent': 'fuse', 'ac-source-mismatch': 'ac-source', 'inverter-ac-mismatch': 'inverter', 'inverter-dc-mismatch': 'inverter',
  }
  if (event.id === 'open-device') return nodes.find(node => node.kind === 'transfer' && node.switchState === 'open' || node.kind === 'fuse' && node.tripped)
  const kind = kindByDiagnostic[event.id]
  return kind ? nodes.find(node => node.kind === kind) : undefined
}
function diagnosticNodeTargets(nodes: SimulationNode[], event: SimulationResult['diagnostics'][number]) {
  const evidenceMatches = nodes.filter(node => event.evidence.includes(node.name) || event.evidence.includes(node.id))
  if (evidenceMatches.length) return evidenceMatches
  const fallback = diagnosticNodeTarget(nodes, event)
  return fallback ? [fallback] : []
}
